	gap: 8px;
	max-width: 88%;
}

.msg-row.user {
	align-self: flex-end;
	flex-direction: row-reverse;
}

.msg-row.bot {
	align-self: flex-start;
}

.bot-badge {
	width: 24px;
	height: 24px;
	border-radius: 50%;
	background: #3b0764;
	color: #e24bff;
	font-size: 0.7rem;
	font-weight: 800;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	margin-top: 2px;
}

.msg-bubble {
	padding: 10px 14px;
	border-radius: 14px;
	font-size: 0.88rem;
	line-height: 1.5;
	word-break: break-word;
}

.msg-bubble.user {
	background: #3b0764;
	color: #ffffff;
	border-bottom-right-radius: 2px;
}

.msg-bubble.bot {
	background: #f3e8ff;
	color: #1a1024;
	border-bottom-left-radius: 2px;
	border: 1px solid #e9d5ff;
}

/* Markdown prose styling */
.msg-text.prose :global(p) {
	margin: 0 0 0.5rem 0;
}

.msg-text.prose :global(p:last-child) {
	margin-bottom: 0;
}

.msg-text.prose :global(ul),
.msg-text.prose :global(ol) {
	margin: 0.35rem 0 0.5rem 1.25rem;
	padding: 0;
}

.msg-text.prose :global(li) {
	margin-bottom: 0.3rem;
}

.msg-text.prose :global(strong) {
	font-weight: 700;
	color: inherit;
}

.msg-text.prose :global(code) {
	background: rgba(0, 0, 0, 0.08);
	padding: 1px 4px;
	border-radius: 4px;
	font-size: 0.88em;
	font-family: monospace;
}

.msg-meta {
	display: flex;
	justify-content: flex-end;
	align-items: center;
	margin-top: 4px;
	font-size: 0.68rem;
	opacity: 0.65;
}

.msg-bubble.thinking {
	display: flex;
	gap: 4px;
	padding: 12px 16px;
}

.dot {
	width: 6px;
	height: 6px;
	background: #9333ea;
	border-radius: 50%;
	animation: pulse 1s infinite alternate;
}

.dot:nth-child(2) {
	animation-delay: 0.2s;
}
.dot:nth-child(3) {
	animation-delay: 0.4s;
}

@keyframes pulse {
	from {
		opacity: 0.3;
		transform: scale(0.8);
	}
	to {
		opacity: 1;
		transform: scale(1.1);
	}
}

.chat-input-area {
	display: flex;
	padding: 12px 14px;
	border-top: 1px solid #ebdcfc;
	background: #ffffff;
	gap: 8px;
	flex-shrink: 0;
}

.chat-input-area input {
	flex: 1;
	border: 1px solid #d8b4fe;
	padding: 10px 14px;
	border-radius: 10px;
	font-size: 0.9rem;
	outline: none;
	font-family: inherit;
	min-height: 44px;
}

.chat-input-area input:focus {
	border-color: #9333ea;
	box-shadow: 0 0 0 2px rgba(147, 51, 234, 0.15);
}

