	background: #3b0764;
	color: #ffffff;
	border: none;
	width: 44px;
	height: 44px;
	border-radius: 10px;
	display: flex;
	align-items: center;
	justify-content: center;
	cursor: pointer;
	transition: background 0.15s;
	font-size: 1rem;
	flex-shrink: 0;
}

.send-btn:hover:not(:disabled) {
	background: #5b1399;
}

.send-btn:disabled {
	opacity: 0.4;
	cursor: not-allowed;
}

