export interface ThemeColors {
	screenBg: string;
	headerBg: string;
	border: string;
	text: string;
	btnBg: string;
	btnText: string;
}

export const THEME_CONFIG: Record<SectionTheme, ThemeColors> = {
	hero: {
		screenBg: '#240340',
		headerBg: '#3b0764',
		border: '#e24bff',
		text: '#e24bff',
		btnBg: '#e24bff',
