args.ReplacementContent:
.prompts-bar {
	display: flex;
	gap: 8px;
	padding: 10px 14px;
	background: #1a0230;
	overflow-x: auto;
	white-space: nowrap;
	border-bottom: none;
	scrollbar-width: thin;
	flex-shrink: 0;
	-webkit-overflow-scrolling: touch;
}

.chip {
	background: #3b0764;
	border: none;
	color: #ffd640;
	padding: 6px 12px;
	border-radius: 9999px;
	font-size: 0.75rem;
	font-weight: 800;
	cursor: pointer;
	transition: all 0.15s;
	flex-shrink: 0;
	min-height: 32px;
	display: inline-flex;
	align-items: center;
}

.chip:hover:not(:disabled) {
	background: #e24bff;
	color: #240340;
}

.chip:disabled {
	opacity: 0.5;
	cursor: not-allowed;
}

.messages-area {
	flex: 1;
	overflow-y: auto;
	padding: 18px 16px;
	display: flex;
	flex-direction: column;
	gap: 14px;
	background: #240340;
}

.message-row {
	display: flex;
	gap: 10px;
	max-width: 88%;
}

.message-row.user {
	align-self: flex-end;
	flex-direction: row-reverse;
}

.message-row.bot {
	align-self: flex-start;
}

.avatar {
	width: 32px;
	height: 32px;
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 0.82rem;
	font-weight: 900;
	flex-shrink: 0;
}

.message-row.bot .avatar {
	background: #e24bff;
	color: #240340;
}

.message-row.user .avatar {
	background: #ffd640;
	color: #4a3000;
}

.bubble {
	padding: 12px 16px;
	border-radius: 14px;
	font-size: 0.92rem;
	line-height: 1.5;
	word-break: break-word;
}

.message-row.user .bubble {
	background: #3b0764;
	color: #f4c7ff;
	border-bottom-right-radius: 2px;
}

.message-row.bot .bubble {
	background: #340557;
	color: #f4c7ff;
	border-bottom-left-radius: 2px;
	border: none;
}

.chat-input-area {
	display: flex;
	padding: 12px 14px;
	border-top: none;
	background: #1a0230;
	gap: 8px;
	flex-shrink: 0;
}

.chat-input-area input {
	flex: 1;
	background: #2e054f;
	border: none;
	color: #f4c7ff;
	padding: 10px 14px;
	border-radius: 10px;
	font-size: 0.9rem;
	outline: none;
	font-family: inherit;
	min-height: 44px;
}

.chat-input-area input::placeholder {
	color: #be7de0;
}

