args.ReplacementContent:
.steps-grid {
	display: grid;
	grid-template-columns: repeat(3, 1fr);
	gap: 2rem;
	position: relative;
}

.step-card {
	border-radius: 20px;
	padding: 2.75rem 2rem;
	text-align: left;
	display: flex;
	flex-direction: column;
	border: none;
	min-height: 340px;
	position: relative;
	background: var(--color-tertiary);
	color: #ffffff;
	transition:
		background-color 0.45s ease,
		color 0.45s ease;
}

.step-badge {
	font-size: 3rem;
	font-weight: 900;
	line-height: 1;
	margin-bottom: 1.25rem;
	color: var(--color-primary);
}

.step-label {
	font-size: 2.2rem;
	font-weight: 900;
	letter-spacing: 0.02em;
	margin-bottom: 0.75rem;
	color: var(--color-primary);
}

.step-text {
	font-size: 1.05rem;
	line-height: 1.5;
	flex: 1;
	color: #ffffff;
	opacity: 0.95;
}

.flat-rule {
	height: 6px;
	width: 44px;
	border-radius: 999px;
	margin-top: 1.5rem;
	background: var(--color-primary);
}

/* SECTIONS 3-6: IMMERSIVE FLAVOUR SCREENS (FLAT, ZERO OUTLINES) */
.flavour-screen {
	position: relative;
	min-height: 100vh;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 6rem 2rem;
	background: transparent;
}

.flavour-content-grid {
	max-width: 1140px;
	width: 100%;
	display: grid;
	grid-template-columns: 460px 1fr;
	gap: 4.5rem;
	align-items: center;
}

.flavour-media-side {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 1.5rem;
}

/* 3D LIFT & FLIP INTERACTIVE CARD (FLAT SOLID SURFACES, ZERO OUTLINES) */
.flip-stage {
	width: 100%;
	max-width: 420px;
	height: 560px;
	perspective: 1200px;
}

.flip-card {
	width: 100%;
	height: 100%;
	position: relative;
	transform-style: preserve-3d;
	transition: transform 0.65s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

.flip-card.flipped {
	transform: translateY(-16px) scale(1.04) rotateY(180deg);
}

.flip-face {
	position: absolute;
	inset: 0;
	backface-visibility: hidden;
	-webkit-backface-visibility: hidden;
	border-radius: 48px;
	border: none;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 0;
	background: transparent;
	filter: drop-shadow(0 20px 48px rgba(0, 0, 0, 0.22));
}

.flip-back {
	transform: rotateY(180deg);
}

/* SIMPLE ROUND ICON FLIP BUTTON */
.round-flip-btn {
	width: 56px;
	height: 56px;
	border-radius: 50%;
	border: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	cursor: pointer;
	background: var(--color-tertiary);
	color: var(--color-primary);
	transition:
		transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1),
		background-color 0.45s ease,
		color 0.45s ease;
}

.round-flip-btn:hover {
	transform: scale(1.12);
}

.round-flip-btn:active {
	transform: scale(0.92);
}

.round-flip-btn .flip-svg {
	width: 26px;
	height: 26px;
	transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.round-flip-btn.is-flipped .flip-svg {
	transform: rotate(180deg);
}

