/* FLAT FOOTER - ZERO OUTLINES */
.site-footer {
	background: transparent;
	color: #ffffff;
	padding: 5rem 1.5rem 7.5rem;
	transition: color 0.45s ease;
}

.footer-inner {
	max-width: 1140px;
	margin: 0 auto;
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
	gap: 2.5rem;
}

.footer-brand-wrap {
	width: 140px;
	margin-bottom: 0.75rem;
}

.footer-tagline {
	font-weight: 900;
	font-size: 1.05rem;
	margin-bottom: 0.75rem;
	color: var(--color-primary);
	letter-spacing: 0.06em;
	transition: color 0.45s ease;
}

.footer-desc {
	font-size: 0.92rem;
	color: #ffffff;
	opacity: 0.85;
	line-height: 1.5;
}

.footer-heading {
	font-size: 1.05rem;
	font-weight: 800;
	color: var(--color-primary);
	margin-bottom: 1rem;
	letter-spacing: 0.03em;
	text-transform: uppercase;
	transition: color 0.45s ease;
}

.footer-links {
	list-style: none;
	display: flex;
	flex-direction: column;
	gap: 0.6rem;
}

.footer-links a,
.footer-link-btn {
	color: #ffffff;
	opacity: 0.9;
	text-decoration: none;
	font-size: 0.92rem;
